public sealed record TessLocalReceiptPreview(Guid Token,bool Ready,ImmutableArray<RuleIssue> Issues,TessLocalReceiptProof? Proof,bool Recorded);
public sealed class TessLocalReceiptBridge
{
    public const string Prefix="R6:personal-bridge:",Actor="CP-TESS";
    private readonly IAdventureRepository _repository;
    private readonly RuntimeCatalog _catalog;
    private readonly ChapterSixPackage _package;
    private readonly Dictionary<Guid,(CommandContext Context,TessLocalReceiptProof Proof)> _previews=[];
    private static readonly ImmutableDictionary<string,int> Sizes=new Dictionary<string,int>{{"tools",3},{"fittings",1},{"lighting",4},{"wind_panels",2},{"archives",2}}.ToImmutableDictionary();
    public TessLocalReceiptBridge(IAdventureRepository repository,RuntimeCatalog catalog,ChapterSixPackage package)
    {ChapterSixPackage.Validate(package);_repository=repository;_catalog=catalog;_package=package;Require(repository.Session.ReleaseId==catalog.ReleaseId,"个人回执与当前发布不一致。");}
    private static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
    private static T? Read<T>(BranchSnapshot s,string id) where T:class=>BranchOperations.Read<T>(s,id);
    private static StoredReceipt Source(BranchSnapshot s,string action,long before,Func<JsonElement,bool> matches)
    {foreach(var r in s.Receipts.Where(r=>r.ActionType==action&&r.Sequence<before).OrderByDescending(r=>r.Sequence)){using var j=JsonDocument.Parse(r.ResultJson);if(matches(j.RootElement))return r;}throw new InvalidOperationException("缺少该节点实际许可、现场工作或收件来源："+action);}
    private static bool S(JsonElement j,string key,string value)=>j.TryGetProperty(key,out var x)&&x.ValueKind==JsonValueKind.String&&x.GetString()==value;
    private static bool B(JsonElement j,string key,bool value)=>j.TryGetProperty(key,out var x)&&(x.ValueKind is JsonValueKind.True or JsonValueKind.False)&&x.GetBoolean()==value;
    private static int N(JsonElement j,string key)=>j.TryGetProperty(key,out var x)&&x.TryGetInt32(out int n)?n:-1;
    private static QuestState Closed(BranchSnapshot s,string node)
    {var q=Read<QuestState>(s,"quest:"+node);Require(q is{Lifecycle:QuestLifecycle.Closed,Outcome:QuestOutcome.Completed}&&q.Id==node&&q.Instance!=Guid.Empty,"必须先在真实章节正文提交中闭合该节点；此入口不能代领任务或奖励。");return q!;}
    private static void Safe(BranchSnapshot s)
    {BranchOperations.Safe(s);Require(!s.Entities.Where(e=>e.Kind=="event").Select(e=>StrictJson.Deserialize<EventSession>(e.Json)).Any(e=>e.State==EventLifecycle.Running),"请先交接当前前景事件。");Require(!s.Entities.Where(e=>e.Kind=="transport_segment").Select(e=>StrictJson.Deserialize<TransportSegment>(e.Json)).Any(t=>t.CargoInTransit&&!t.Completed),"真实运输尚未安全交接。");Require(!BranchOperations.Receipt(s,"Q-604")&&BranchOperations.Entity(s,"final:preparation") is null,"最终封存后本地回执登记暂停，请读取保护档。");}
    public static string Stand(string node)=>node switch{"CQ-TESS-01"=>"R6-S05.contacts","CQ-TESS-02"=>"R6-S05.supplement","CQ-TESS-03"=>"R6-S08.local_notice",_=>throw new InvalidOperationException("这里只登记三个已有泰丝本地节点。")};
    private void At(BranchSnapshot s,string node)
    {string spot=Stand(node);var g=_package.Scenes.Single(x=>x.Geometry.Id==spot.Split('.')[0]).Geometry;var a=Read<ActorState>(s,"actor");Require(a is not null&&a.Scene==g.Id&&a.Position.Distance(g.Spots.Single(x=>x.Id==spot).Stand)<=2.5&&new NavigationGrid(g).CanStand(a.Position,true),"请实际走到该节点原有安全核对站位。");}
    private void Material(BranchSnapshot s,string id)
    {var m=_package.Materials.Single(x=>x.Id==id);var a=Read<ChapterMaterialAccess>(s,"material:"+id);Require(a is not null&&a.Id==m.Id&&a.Version==m.Version&&a.TranslationVersion==m.TranslationVersion&&a.Fingerprint==m.Fingerprint&&a.SourceRoot==m.SourceRoot,"原材料未实际取得或版本已变，不能从目录借证。");}
    private TessLocalReceiptProof Verify(BranchSnapshot s,string node)
    {
        Safe(s);At(s,node);var st=Read<ChapterSixState>(s,"chapter6")??throw new InvalidOperationException("边境没有实际初始化。");Require(st.ContentVersion==_package.Version&&st.Landing&&st.TessInvitation=="accept"&&s.Receipts.Any(r=>r.ActionType=="chapter_six_region_initialized"),"需要实际边境登记及本人当前邀请；正式同行不构成门槛。");var q=Closed(s,node);string action=node switch{"CQ-TESS-01"=>"chapter_six_tess_contacts_received","CQ-TESS-02"=>"chapter_six_tess_trip_review_received",_=>"chapter_six_tess_notice_received"};var close=s.Receipts.SingleOrDefault(r=>r.SemanticKey==node+":resolution"&&r.ActionType==action)??throw new InvalidOperationException("该节点不是实际第六章原预算结算来源。");using(var cj=JsonDocument.Parse(close.ResultJson))Require(S(cj.RootElement,"quest",node)&&(node!="CQ-TESS-01"||B(cj.RootElement,"current_contacts",true))&&(node!="CQ-TESS-03"||B(cj.RootElement,"recipient_confirmation",true)&&B(cj.RootElement,"local_scope_only",true)),"节点收件回执不符。");
        string main=node=="CQ-TESS-01"?"Q-601":"Q-603";var mq=Closed(s,main);var mr=s.Receipts.SingleOrDefault(r=>r.SemanticKey==main+":resolution"&&r.ActionType=="main_quest_resolution")??throw new InvalidOperationException("真实主线实例未闭合。");var m=StrictJson.Deserialize<Mist.Core.ReleaseReadiness.MainQuestResolution>(mr.ResultJson);Require(m.Quest==main&&m.Instance==mq.Instance&&m.Outcome=="completed"&&mr.Sequence<close.Sequence,"主线实例或实际先后不符。");
        var latest=Source(s,"chapter_six_tess_invitation",long.MaxValue,j=>S(j,"actor",Actor));using(var lj=JsonDocument.Parse(latest.ResultJson))Require(S(lj.RootElement,"decision","accept"),"当前本人许可已撤回或暂缓。");var invitation=Source(s,"chapter_six_tess_invitation",close.Sequence,j=>S(j,"actor",Actor)&&S(j,"decision","accept")&&S(j,"source_quest","Q-601:resolution")&&B(j,"no_main_permission_gate",true));Require(invitation.Sequence> s.Receipts.Single(r=>r.SemanticKey=="Q-601:resolution").Sequence,"实际邀请须在公开调查闭合以后。");
        var sources=ImmutableArray.CreateBuilder<string>();sources.Add(close.ReceiptId);sources.Add(mr.ReceiptId);sources.Add(invitation.ReceiptId);string outcome;string? planId=null;Guid? segment=null;ImmutableArray<string> arrivals=[],boxes=[];
        switch(node)
        {
            case "CQ-TESS-01":
                Material(s,"R6-CQTESS01-R-CONTACTS");Require(st!.TessRecipients,"现行接收岗未核对。");var contacts=Source(s,"chapter_six_tess_current_contacts",close.Sequence,j=>S(j,"shed","ROLE-R6-SHED-RECEIVER")&&S(j,"ridge","ROLE-R6-RIDGE-RECEIVER")&&S(j,"conditions","complete_labels_same_current_manifest")&&S(j,"source_manifest",_package.Version));Require(contacts.Sequence>invitation.Sequence,"联系页早于本人许可。");sources.Add(contacts.ReceiptId);outcome="现场交接窗口";break;
            case "CQ-TESS-02":
                Closed(s,"CQ-TESS-01");Material(s,"R6-CQTESS02-R-TRIPS");Material(s,"R6-Q603-R-LOAD");var plan=Source(s,"chapter_six_optional_supplement_plan",close.Sequence,j=>S(j,"stock_scope","independent_optional_not_base_or_transition"));planId=plan.ReceiptId;using(var pj=JsonDocument.Parse(plan.ResultJson))
                {string decision=pj.RootElement.GetProperty("decision").GetString()!;var trips=pj.RootElement.GetProperty("trips").EnumerateObject().ToImmutableDictionary(x=>x.Name,x=>x.Value.GetInt32());Require(decision==st!.SupplementDecision&&trips.Count==st.SupplementTrips.Count&&trips.All(x=>st.SupplementTrips.GetValueOrDefault(x.Key)==x.Value),"当前补充计划与原始承诺不符。");sources.Add(plan.ReceiptId);
                 if(decision=="decline"){Require(trips.Count==0&&st.SupplementDelivered==0&&!s.Receipts.Any(r=>r.ActionType=="chapter_six_optional_supplement_arrival"),"未承诺不得附带到货或运输完成记录。");using var review=JsonDocument.Parse(close.ResultJson);Require(B(review.RootElement,"not_committed",true)&&N(review.RootElement,"actually_delivered")==0,"未承诺的正式收束不符。");Require(Sizes.Keys.All(k=>s.Items.Single(i=>i.Id=="R6-supplement:"+k) is{OwnerKind:"warehouse",OwnerId:"R6-S05:supplement"}),"未承诺的独立货组被挪用。");outcome="未承担补充运输";}
                 else{Require(decision=="accept"&&st.SupplementDelivered==2&&trips.Count==5&&Sizes.Keys.All(trips.ContainsKey)&&trips.Values.All(t=>t is 1 or 2)&&Enumerable.Range(1,2).All(t=>trips.Where(x=>x.Value==t).Sum(x=>Sizes[x.Key])<=6)&&trips["tools"]<trips["lighting"]&&trips["fittings"]<trips["lighting"],"原有两趟整箱规则或真实交付缺失。");using var review=JsonDocument.Parse(close.ResultJson);Require(B(review.RootElement,"not_committed",false)&&N(review.RootElement,"actually_delivered")==2&&review.RootElement.GetProperty("original_trips").EnumerateObject().All(x=>trips.GetValueOrDefault(x.Name)==x.Value.GetInt32()),"正式回顾未引用同一计划。");var ar=ImmutableArray.CreateBuilder<string>();long previous=plan.Sequence;for(int t=1;t<=2;t++){var receipt=s.Receipts.SingleOrDefault(r=>r.SemanticKey=="R6:supplement:trip:"+t&&r.ActionType=="chapter_six_optional_supplement_arrival")??throw new InvalidOperationException("原运输缺一趟实际到货。");using var a=JsonDocument.Parse(receipt.ResultJson);var actual=a.RootElement.GetProperty("actual_boxes").EnumerateArray().Select(x=>x.GetString()!).ToArray();var expected=trips.Where(x=>x.Value==t).Select(x=>"R6-supplement:"+x.Key).ToArray();Require(receipt.Sequence>previous&&receipt.Sequence<close.Sequence&&N(a.RootElement,"trip")==t&&N(a.RootElement,"parent_reward")==0&&S(a.RootElement,"qualified_commissioned_driver","ROLE-R6-CART-DRIVER")&&S(a.RootElement,"receiving_scope","optional_settlement_supplement")&&actual.Order().SequenceEqual(expected.Order())&&a.RootElement.GetProperty("safe_route_receipts").EnumerateArray().Select(x=>x.GetString()!).Order().SequenceEqual(new[]{"R6:ENC-R6-03:result","R6:ENC-R6-04:result"}.Order()),"到货箱号、真实顺序、安全段或接收范围不符。");foreach(string enc in new[]{"ENC-R6-03","ENC-R6-04"}){var safe=s.Receipts.Single(r=>r.SemanticKey=="R6:"+enc+":result"&&r.ActionType=="chapter_six_encounter_result");Require(safe.Sequence<receipt.Sequence&&StrictJson.Deserialize<FrontierEncounterResult>(safe.ResultJson).Completed,"货组不能引用未完成的路线处置。");}previous=receipt.Sequence;ar.Add(receipt.ReceiptId);}boxes=Sizes.Keys.Select(k=>"R6-supplement:"+k).Order().ToImmutableArray();Require(boxes.All(id=>s.Items.Single(i=>i.Id==id) is{OwnerKind:"installed",OwnerId:"R6:optional_settlement_supplement"} item&&item.DefinitionId=="R6-SUPPLEMENT-"+id.Split(':')[1].ToUpperInvariant()),"同一五箱实物当前接收归属不符。");arrivals=ar.ToImmutable();sources.AddRange(arrivals);segment=Guid.Parse(plan.ReceiptId);outcome=trips["wind_panels"]==1?"面板先到":"档案先到";}}
                break;
            default:
                Closed(s,"CQ-TESS-02");Material(s,"R6-CQTESS03-R-NOTICE");Require(st!.TessMessage&&st.TessSecondContact&&st.TessReceivingConfirmed&&st.CargoDelivered,"真实地方通知闭环未成立。");var sent=Source(s,"chapter_six_local_notice_receiving_confirmed",close.Sequence,j=>S(j,"actual_recipient","ROLE-R6-NEXT-WATCH")&&S(j,"copy_recipient","ROLE-R6-NOTICE-BACKUP")&&S(j,"confirmation","bounded_local_delivery_sheet_received")&&B(j,"protocol_signature",false));using(var sj=JsonDocument.Parse(sent.ResultJson)){long version=sj.RootElement.GetProperty("receiving_record_version").GetInt64();var prepared=Source(s,"chapter_six_tess_notice_prepared",sent.Sequence,j=>S(j,"first","ROLE-R6-NEXT-WATCH")&&S(j,"second","ROLE-R6-NOTICE-BACKUP")&&S(j,"record","current_delivery_sheet")&&j.GetProperty("record_version").GetInt64()==version&&B(j,"main_delivery_present",true)&&B(j,"protocol_signature",false));Require(prepared.Sequence>invitation.Sequence,"本地通知早于本人许可。");sources.Add(prepared.ReceiptId);sources.Add(sent.ReceiptId);}outcome="具名本地交接并保持联络";break;
        }
        var definition=new CompanionArcService(_repository,_catalog).Definitions[node];Require(definition.Actor==Actor&&definition.Outcomes.Contains(outcome)&&definition.Xp==(node=="CQ-TESS-01"?25:node=="CQ-TESS-03"?40:0)&&definition.Marks==(node=="CQ-TESS-01"?20:node=="CQ-TESS-03"?30:0)&&definition.Parts==0,"原件个人预算或有界收束不符。");return new(node,q.Instance,outcome,close.ReceiptId,mr.ReceiptId,mq.Instance,invitation.ReceiptId,_package.Version,sources.ToImmutable(),planId,segment,arrivals,boxes);
    }
    private string[] Reads(BranchSnapshot s,string node)=>s.Entities.Select(e=>e.Id).Concat(new[]{"personal:"+node,"private-invitation:"+node,Prefix+node,Prefix+node+":projection"}).Distinct().ToArray();
    private CommitPlanCommand Plan(BranchSnapshot s,TessLocalReceiptProof p,string stage,string action,object payload,ImmutableArray<EntityChange> changes=default)
        =>BranchOperations.Plan(_repository,s,Prefix+p.Node+":"+p.NodeInstance+":"+stage,action,changes.IsDefault?[]:changes,Reads(s,p.Node),payload,items:p.BoxSerials.Select(id=>{var i=s.Items.Single(i=>i.Id==id);return new ItemChange(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,i.OwnerKind,i.OwnerId,i.Slot);}).ToImmutableArray());
    public async ValueTask<TessLocalReceiptPreview> PreviewRecordAsync(string node)
    {var s=await _repository.SnapshotAsync();try{var p=Verify(s,node);var old=Read<TessLocalReceiptProjection>(s,Prefix+node+":projection");if(old is not null){Require(StrictJson.Serialize(old.Proof)==StrictJson.Serialize(p),"已登记个人来源不能改写。");return new(Guid.Empty,true,[],p,true);}var c=Plan(s,p,"preview","readonly_personal_receipt_preview",p);Guid token=Guid.NewGuid();_previews[token]=(c.Context,p);return new(token,true,[],p,false);}catch(InvalidOperationException e){return new(Guid.Empty,false,[new("actual_local_result_missing",node,e.Message)],null,false);}}
    public void ClosePreview(Guid token)=>_previews.Remove(token);
    public async ValueTask<TessLocalReceiptProjection?> ReadProjectionAsync(string node)=>Read<TessLocalReceiptProjection>(await _repository.SnapshotAsync(),Prefix+node+":projection");
    public async ValueTask<CommandResult> ConfirmRecordAsync(Guid token)
    {
        if(!_previews.TryGetValue(token,out var prepared))return new(CommitStatus.Rejected,null,[new("preview_closed",Prefix,"核对清单已关闭或未就绪。")]);var session=_repository.Session;var c=prepared.Context;if(c.Profile!=session.Profile||c.Branch!=session.Branch||c.Load!=session.Load||c.ReleaseId!=session.ReleaseId)return new(CommitStatus.Rejected,null,[new("stale_load",Prefix,"读取世代已改变，请重开实际核对。")]);var snapshot=await _repository.SnapshotAsync();if(c.Expected.Any(x=>(BranchOperations.Entity(snapshot,x.EntityId)?.Revision??-1)!=x.Revision))return new(CommitStatus.Rejected,null,[new("stale_sources",Prefix,"站位、本人许可或实际来源改变，请重新核对。")]);if(_repository is not IEventLeaseStore leases)throw new InvalidOperationException("实际本地登记需要前景原子占用。");string owner="tess-receipt:"+Guid.NewGuid();Require(await leases.TryLeasesAsync(c.Load,owner,["input:foreground"]),"另一前景工作尚未交接。");try{return await Publish(prepared.Proof);}finally{await leases.ReleaseLeasesAsync(c.Load,owner);}
    }
    private async ValueTask<CommandResult> Publish(TessLocalReceiptProof expected)
    {
        async ValueTask<StoredReceipt> Stage(string name,string action,Func<BranchSnapshot,object> result,Func<BranchSnapshot,ImmutableArray<EntityChange>>? changes=null)
        {var s=await _repository.SnapshotAsync();var p=Verify(s,expected.Node);Require(StrictJson.Serialize(p)==StrictJson.Serialize(expected),"原始收束或补充箱来源改变，请重开清单。");string key=Prefix+p.Node+":"+p.NodeInstance+":"+name;var old=s.Receipts.SingleOrDefault(r=>r.SemanticKey==key);if(old is not null){Require(old.ActionType==action&&old.ResultJson==StrictJson.Serialize(result(s)),"已提交的个人桥阶段不能换来源。");return old;}var commit=await _repository.ExecuteAsync(Plan(s,p,name,action,result(s),changes?.Invoke(s)??[]));Require(commit.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"个人登记因实际来源改变未提交。");return (await _repository.SnapshotAsync()).Receipts.Single(r=>r.SemanticKey==key);}
        var invitation=await Stage("invitation","private_invitation_verified",_=>new PrivateInvitationAuthority(Actor,expected.Node,true),s=>[BranchOperations.Change(s,Prefix+expected.Node,"actual_tess_receipt_source",expected)]);
        StoredReceipt? transport=null;if(expected.SegmentInstance is{} segment)transport=await Stage("transport","escort_segment_result",_=>new EscortSegmentResult("Q-603",expected.MainQuestInstance,"PZ-Q603-LOAD",segment,expected.Outcome,true));
        // The original plan receipt is the stable instance of the already-performed optional segment.
        var work=await Stage("work",CompanionArcService.RequiredWorkAction(expected.Node),_=>new PersonalWorkEvidence(expected.Node,Actor,expected.NodeInstance,expected.Outcome,invitation.ReceiptId,transport?.ReceiptId));
        var result=await Stage("result","personal_work_verified",_=>new PersonalWorkResult(expected.Node,Actor,expected.Outcome,work.ReceiptId,TransportResultReceipt:transport?.ReceiptId,MeetingConsentReceipts:[],NodeInstance:expected.NodeInstance,ContactConsentReceipts:[]));
        var s=await _repository.SnapshotAsync();Require(StrictJson.Serialize(Verify(s,expected.Node))==StrictJson.Serialize(expected),"登记前来源已改变。");var oldProjection=Read<TessLocalReceiptProjection>(s,Prefix+expected.Node+":projection");if(oldProjection is not null){Require(oldProjection.ResultReceipt==result.ReceiptId,"同一结果不能替换。");return new(CommitStatus.AlreadyCommitted,null,[]);}var oldNode=Read<PersonalNodeState>(s,"personal:"+expected.Node);Require(oldNode is null||oldNode.Instance==expected.NodeInstance&&!oldNode.Completed,"旧个人实例不符，不能覆盖另一工作或奖励。");var projection=new TessLocalReceiptProjection(expected,invitation.ReceiptId,transport?.ReceiptId,work.ReceiptId,result.ReceiptId,0,0,false);
        return await _repository.ExecuteAsync(Plan(s,expected,"projection","chapter_six_personal_receipts_projected",projection,[BranchOperations.Change(s,"personal:"+expected.Node,"personal_node",new PersonalNodeState(expected.Node,expected.NodeInstance,true,true,expected.Outcome,result.ReceiptId)),BranchOperations.Change(s,"private-invitation:"+expected.Node,"private_invitation",new PrivateInvitation(Actor,expected.Node,true,invitation.ReceiptId)),BranchOperations.Change(s,Prefix+expected.Node+":projection","actual_tess_receipt_projection",projection)]));
    }
}
